'use strict';

/**
 * Minimal PKCS#10 (RFC 2986) CertificationRequest builder and verifier.
 *
 * Implemented with Node's built-in `crypto` module and hand-rolled ASN.1 DER
 * encoding so the project does not depend on the `openssl` CLI being present
 * (it is not installed on Windows by default).
 *
 * Output:
 *   - private key: PKCS#8 (generated by scripts/generate-dev-keys.js)
 *   - public key:  SubjectPublicKeyInfo (SPKI)
 *   - CSR:         PKCS#10, signed with RSA-SHA256 (PKCS#1 v1.5)
 */

const crypto = require('node:crypto');

const OIDS = Object.freeze({
  sha256WithRSAEncryption: '1.2.840.113549.1.1.11',
  rsaEncryption: '1.2.840.113549.1.1.1',
  countryName: '2.5.4.6',
  stateOrProvinceName: '2.5.4.8',
  localityName: '2.5.4.7',
  organizationName: '2.5.4.10',
  commonName: '2.5.4.3',
  emailAddress: '1.2.840.113549.1.9.1',
});

// ---- ASN.1 DER primitives ------------------------------------------------

function derLength(length) {
  if (length < 0x80) return Buffer.from([length]);
  const bytes = [];
  let remaining = length;
  while (remaining > 0) {
    bytes.unshift(remaining & 0xff);
    remaining = Math.floor(remaining / 256);
  }
  return Buffer.from([0x80 | bytes.length, ...bytes]);
}

function derTag(tag, content) {
  return Buffer.concat([Buffer.from([tag]), derLength(content.length), content]);
}

function derSequence(...items) {
  return derTag(0x30, Buffer.concat(items));
}

function derSet(...items) {
  return derTag(0x31, Buffer.concat(items));
}

function derOid(oid) {
  const parts = oid.split('.').map(Number);
  const out = [parts[0] * 40 + parts[1]];
  for (let i = 2; i < parts.length; i += 1) {
    let value = parts[i];
    const encoded = [value & 0x7f];
    value = Math.floor(value / 128);
    while (value > 0) {
      encoded.unshift((value & 0x7f) | 0x80);
      value = Math.floor(value / 128);
    }
    out.push(...encoded);
  }
  return derTag(0x06, Buffer.from(out));
}

function derInteger(value) {
  let buf;
  if (value === 0) {
    buf = Buffer.from([0]);
  } else {
    const bytes = [];
    let remaining = value;
    while (remaining > 0) {
      bytes.unshift(remaining & 0xff);
      remaining = Math.floor(remaining / 256);
    }
    if (bytes[0] & 0x80) bytes.unshift(0);
    buf = Buffer.from(bytes);
  }
  return derTag(0x02, buf);
}

function derNull() {
  return Buffer.from([0x05, 0x00]);
}

function derBitString(buffer) {
  // First content byte is the number of unused bits in the final octet (0).
  return derTag(0x03, Buffer.concat([Buffer.from([0x00]), buffer]));
}

function derUtf8String(value) {
  return derTag(0x0c, Buffer.from(value, 'utf8'));
}

function derPrintableString(value) {
  return derTag(0x13, Buffer.from(value, 'ascii'));
}

function derIa5String(value) {
  return derTag(0x16, Buffer.from(value, 'ascii'));
}

function derAlgorithmIdentifier(oid) {
  return derSequence(derOid(oid), derNull());
}

function derAttributeTypeAndValue(oid, valueDer) {
  return derSequence(derOid(oid), valueDer);
}

function derName(rdns) {
  return derSequence(...rdns);
}

// ---- PKCS#10 construction -------------------------------------------------

function derSubject(subject) {
  const rdns = [];
  if (subject.countryName) {
    rdns.push(derSet(derAttributeTypeAndValue(OIDS.countryName, derPrintableString(subject.countryName))));
  }
  if (subject.stateOrProvinceName) {
    rdns.push(derSet(derAttributeTypeAndValue(OIDS.stateOrProvinceName, derUtf8String(subject.stateOrProvinceName))));
  }
  if (subject.localityName) {
    rdns.push(derSet(derAttributeTypeAndValue(OIDS.localityName, derUtf8String(subject.localityName))));
  }
  if (subject.organizationName) {
    rdns.push(derSet(derAttributeTypeAndValue(OIDS.organizationName, derUtf8String(subject.organizationName))));
  }
  if (subject.commonName) {
    rdns.push(derSet(derAttributeTypeAndValue(OIDS.commonName, derUtf8String(subject.commonName))));
  }
  if (subject.emailAddress) {
    rdns.push(derSet(derAttributeTypeAndValue(OIDS.emailAddress, derIa5String(subject.emailAddress))));
  }
  if (rdns.length === 0) {
    rdns.push(derSet(derAttributeTypeAndValue(OIDS.commonName, derUtf8String('localhost'))));
  }
  return derName(rdns);
}

function derCertificationRequestInfo(version, subjectDer, spkiDer) {
  const attributes = derTag(0xa0, Buffer.alloc(0)); // [0] IMPLICIT empty SET OF
  return derSequence(derInteger(version), subjectDer, spkiDer, attributes);
}

/**
 * Build a PKCS#10 CertificationRequest (DER).
 *
 * @param {object} deps
 * @param {crypto.KeyObject} deps.privateKey RSA private key.
 * @param {crypto.KeyObject} deps.publicKey RSA public key.
 * @param {{countryName?: string, organizationName?: string, commonName?: string}} [deps.subject]
 * @returns {Buffer} DER-encoded PKCS#10 request.
 */
function createCsrDer({ privateKey, publicKey, subject = {} }) {
  const spkiDer = publicKey.export({ type: 'spki', format: 'der' });
  const subjectDer = derSubject(subject);
  const csrInfoDer = derCertificationRequestInfo(0, subjectDer, spkiDer);
  const signature = crypto.sign('RSA-SHA256', csrInfoDer, privateKey);
  return derSequence(
    csrInfoDer,
    derAlgorithmIdentifier(OIDS.sha256WithRSAEncryption),
    derBitString(signature)
  );
}

// ---- PKCS#10 verification -------------------------------------------------

function readTlv(buf, offset) {
  const start = offset;
  const tag = buf[offset];
  offset += 1;
  let length = buf[offset];
  offset += 1;
  if (length & 0x80) {
    const count = length & 0x7f;
    length = 0;
    for (let i = 0; i < count; i += 1) {
      length = (length << 8) | buf[offset];
      offset += 1;
    }
  }
  return { tag, content: buf.subarray(offset, offset + length), start, end: offset + length };
}

/**
 * Verify a PKCS#10 request's self-signature using the public key embedded in
 * the request itself. Throws a descriptive Error on any structural problem or
 * signature mismatch; returns true when valid.
 *
 * @param {Buffer} csrDer DER-encoded PKCS#10 request.
 * @returns {boolean}
 */
function verifyCsrDer(csrDer) {
  const outer = readTlv(csrDer, 0);
  if (outer.tag !== 0x30) throw new Error('PKCS#10: expected SEQUENCE');

  const info = readTlv(outer.content, 0);
  if (info.tag !== 0x30) throw new Error('PKCS#10: expected CertificationRequestInfo SEQUENCE');

  const algorithm = readTlv(outer.content, info.end);
  if (algorithm.tag !== 0x30) throw new Error('PKCS#10: expected AlgorithmIdentifier SEQUENCE');

  const signature = readTlv(outer.content, algorithm.end);
  if (signature.tag !== 0x03) throw new Error('PKCS#10: expected BIT STRING signature');
  if (signature.end !== outer.content.length) throw new Error('PKCS#10: trailing data after signature');

  const infoBytes = outer.content.subarray(0, info.end);

  // Parse CertificationRequestInfo: version, subject Name, subjectPKInfo, attributes.
  const version = readTlv(info.content, 0);
  const subject = readTlv(info.content, version.end);
  const spki = readTlv(info.content, subject.end);
  if (spki.tag !== 0x30) throw new Error('PKCS#10: expected SubjectPublicKeyInfo SEQUENCE');

  const spkiDer = info.content.subarray(spki.start, spki.end);
  const publicKey = crypto.createPublicKey({ key: spkiDer, format: 'der', type: 'spki' });

  const unusedBits = signature.content[0];
  if (unusedBits !== 0) throw new Error('PKCS#10: unexpected unused bits in signature');

  const valid = crypto.verify('RSA-SHA256', infoBytes, publicKey, signature.content.subarray(1));
  if (!valid) throw new Error('PKCS#10: signature verification failed');
  return true;
}

function pemEncode(der, label) {
  const base64 = der.toString('base64');
  const lines = base64.match(/.{1,64}/g).join('\n');
  return `-----BEGIN ${label}-----\n${lines}\n-----END ${label}-----\n`;
}

module.exports = { createCsrDer, verifyCsrDer, pemEncode };
